18	// The characters by which spacing, inline content and pins are replaced in the
19	// full text.
20	const SPACING_REPLACE: &str = " "; // Space
21	const OBJ_REPLACE: &str = "\u{FFFC}"; // Object Replacement Character
22	
23	// Unicode BiDi control characters.
24	const LTR_EMBEDDING: &str = "\u{202A}";
25	const RTL_EMBEDDING: &str = "\u{202B}";
26	const POP_EMBEDDING: &str = "\u{202C}";
27	const LTR_ISOLATE: &str = "\u{2066}";
28	const POP_ISOLATE: &str = "\u{2069}";
29	
30	/// A prepared item in a inline layout.
31	#[derive(Debug)]
32	pub enum Item<'a> {
33	    /// A shaped text run with consistent style and direction.
34	    Text(ShapedText<'a>),
35	    /// Absolute spacing between other items, and whether it is weak.
36	    Absolute(Abs, bool),
37	    /// Fractional spacing between other items.
38	    Fractional(Fr, Option<(&'a Packed<BoxElem>, Locator<'a>, StyleChain<'a>)>),
39	    /// Layouted inline-level content.
40	    Frame(Frame),
41	    /// A tag.
42	    Tag(&'a Tag),
43	    /// An item that is invisible and needs to be skipped, e.g. a Unicode
44	    /// isolate.
45	    Skip(&'static str),
46	}
47	
48	impl<'a> Item<'a> {
49	    /// Whether this is a tag item.
50	    pub fn is_tag(&self) -> bool {
51	        matches!(self, Self::Tag(_))
52	    }
53	
54	    /// If this a text item, return it.
55	    pub fn text(&self) -> Option<&ShapedText<'a>> {
56	        match self {
57	            Self::Text(shaped) => Some(shaped),
58	            _ => None,
59	        }
60	    }
61	
62	    /// If this a text item, return it mutably.
63	    pub fn text_mut(&mut self) -> Option<&mut ShapedText<'a>> {
64	        match self {
65	            Self::Text(shaped) => Some(shaped),
66	            _ => None,
67	        }
68	    }
69	
70	    /// Return the textual representation of this item: Either just itself (for
71	    /// a text item) or a replacement string (for any other item).
72	    pub fn textual(&self) -> &str {
73	        match self {
74	            Self::Text(shaped) => shaped.text,
75	            Self::Absolute(_, _) | Self::Fractional(_, _) => SPACING_REPLACE,
76	            Self::Frame(_) => OBJ_REPLACE,
77	            Self::Tag(_) => "",
78	            Self::Skip(s) => s,
79	        }
80	    }
81	
82	    /// The text length of the item.
83	    pub fn textual_len(&self) -> usize {
84	        self.textual().len()
85	    }
86	
87	    /// The natural layouted width of the item.
88	    pub fn natural_width(&self) -> Abs {
89	        match self {
90	            Self::Text(shaped) => shaped.width(),
91	            Self::Absolute(v, _) => *v,
92	            Self::Frame(frame) => frame.width(),
93	            Self::Fractional(_, _) | Self::Tag(_) => Abs::zero(),
94	            Self::Skip(_) => Abs::zero(),
95	        }
96	    }
97	}
98	
99	/// An item or not-yet shaped text. We can't shape text until we have collected
100	/// all items because only then we can compute BiDi, and we need to split shape
101	/// runs at level boundaries.
102	#[derive(Debug)]
103	pub enum Segment<'a> {
104	    /// One or multiple collapsed text children. Stores how long the segment is
105	    /// (in bytes of the full text string).
106	    Text(usize, StyleChain<'a>),
107	    /// An already prepared item.
108	    Item(Item<'a>),
109	}
110	
111	impl Segment<'_> {
112	    /// The text length of the item.
113	    pub fn textual_len(&self) -> usize {
114	        match self {
115	            Self::Text(len, _) => *len,
116	            Self::Item(item) => item.textual_len(),
117	        }
118	    }
119	}
120	
121	/// Collects all text into one string and a collection of segments that
122	/// correspond to pieces of that string. This also performs string-level
123	/// preprocessing like case transformations.
124	#[typst_macros::time]
125	pub fn collect<'a>(
126	    children: &[Pair<'a>],
127	    engine: &mut Engine<'_>,
128	    locator: &mut SplitLocator<'a>,
129	    config: &Config,
130	    region: Size,
131	) -> SourceResult<(String, Vec<Segment<'a>>, SpanMapper)> {
132	    let mut collector = Collector::new(2 + children.len());
133	    let mut quoter = SmartQuoter::new();
134	
135	    if !config.first_line_indent.is_zero() {
136	        collector.push_item(Item::Absolute(config.first_line_indent, false));
137	        collector.spans.push(1, Span::detached());
138	    }
139	
140	    if !config.hanging_indent.is_zero() {
141	        collector.push_item(Item::Absolute(-config.hanging_indent, false));
142	        collector.spans.push(1, Span::detached());
143	    }
144	
145	    for &(child, styles) in children {
146	        let prev_len = collector.full.len();
147	
148	        if child.is::<SpaceElem>() {
149	            collector.push_text(" ", styles);
150	        } else if let Some(elem) = child.to_packed::<TextElem>() {
151	            collector.build_text(styles, |full| {
152	                let dir = styles.resolve(TextElem::dir);
153	                if dir != config.dir {
154	                    // Insert "Explicit Directional Embedding".
155	                    match dir {
156	                        Dir::LTR => full.push_str(LTR_EMBEDDING),
157	                        Dir::RTL => full.push_str(RTL_EMBEDDING),
158	                        _ => {}
159	                    }
160	                }
161	
162	                if let Some(case) = styles.get(TextElem::case) {
163	                    full.push_str(&case.apply(&elem.text));
164	                } else {
165	                    full.push_str(&elem.text);
166	                }
167	
168	                if dir != config.dir {
169	                    // Insert "Pop Directional Formatting".
170	                    full.push_str(POP_EMBEDDING);
171	                }
172	            });
173	        } else if let Some(elem) = child.to_packed::<HElem>() {
174	            if elem.amount.is_zero() {
175	                continue;
176	            }
177	
178	            collector.push_item(match elem.amount {
179	                Spacing::Fr(fr) => Item::Fractional(fr, None),
180	                Spacing::Rel(rel) => Item::Absolute(
181	                    rel.resolve(styles).relative_to(region.x),
182	                    elem.weak.get(styles),
183	                ),
184	            });
185	        } else if let Some(elem) = child.to_packed::<LinebreakElem>() {
186	            collector.push_text(
187	                if elem.justify.get(styles) { "\u{2028}" } else { "\n" },
188	                styles,
189	            );
190	        } else if let Some(elem) = child.to_packed::<SmartQuoteElem>() {
191	            let double = elem.double.get(styles);
192	            if elem.enabled.get(styles) {
193	                let quotes = SmartQuotes::get(
194	                    elem.quotes.get_ref(styles),
195	                    styles.get(TextElem::lang),
196	                    styles.get(TextElem::region),
197	                    elem.alternative.get(styles),
198	                );
199	                let before =
200	                    collector.full.chars().rev().find(|&c| !is_default_ignorable(c));
201	                let quote = quoter.quote(before, &quotes, double);
202	                collector.push_text(quote, styles);
203	            } else {
204	                collector.push_text(SmartQuotes::fallback(double), styles);
205	            }
206	        } else if let Some(elem) = child.to_packed::<InlineElem>() {
207	            collector.push_item(Item::Skip(LTR_ISOLATE));
208	
209	            for item in elem.layout(engine, locator.next(&elem.span()), styles, region)? {
210	                match item {
211	                    InlineItem::Space(space, weak) => {
212	                        collector.push_item(Item::Absolute(space, weak));
213	                    }
214	                    InlineItem::Frame(mut frame) => {
215	                        frame.modify(&FrameModifiers::get_in(styles));
216	                        apply_shift(&engine.world, &mut frame, styles);
217	                        collector.push_item(Item::Frame(frame));
218	                    }
219	                }
220	            }
221	
222	            collector.push_item(Item::Skip(POP_ISOLATE));
223	        } else if let Some(elem) = child.to_packed::<BoxElem>() {
224	            let loc = locator.next(&elem.span());
225	            if let Sizing::Fr(v) = elem.width.get(styles) {
226	                collector.push_item(Item::Fractional(v, Some((elem, loc, styles))));
227	            } else {
228	                let mut frame = layout_and_modify(styles, |styles| {
229	                    layout_box(elem, engine, loc, styles, region)
230	                })?;
231	                apply_shift(&engine.world, &mut frame, styles);
232	                collector.push_item(Item::Frame(frame));
233	            }
234	        } else if let Some(elem) = child.to_packed::<TagElem>() {
235	            collector.push_item(Item::Tag(&elem.tag));
236	        } else {
237	            // Non-paragraph inline layout should never trigger this since it
238	            // only won't be triggered if we see any non-inline content.
239	            engine.sink.warn(warning!(
240	                child.span(),
241	                "{} may not occur inside of a paragraph and was ignored",
242	                child.func().name(),
243	            ));
244	        }
245	
246	        let len = collector.full.len() - prev_len;
247	        collector.spans.push(len, child.span());
248	    }
249	
250	    Ok((collector.full, collector.segments, collector.spans))
251	}
252	
253	/// Collects segments.
254	struct Collector<'a> {
255	    full: String,
256	    segments: Vec<Segment<'a>>,
257	    spans: SpanMapper,
258	}
259	
260	impl<'a> Collector<'a> {
261	    fn new(capacity: usize) -> Self {
262	        Self {
263	            full: String::new(),
264	            segments: Vec::with_capacity(capacity),
265	            spans: SpanMapper::new(),
266	        }
267	    }
268	
269	    fn push_text(&mut self, text: &str, styles: StyleChain<'a>) {
270	        self.build_text(styles, |full| full.push_str(text));
271	    }
272	
273	    fn build_text<F>(&mut self, styles: StyleChain<'a>, f: F)
274	    where
275	        F: FnOnce(&mut String),
276	    {
277	        let prev = self.full.len();
278	        f(&mut self.full);
279	        let segment_len = self.full.len() - prev;
280	
281	        // Merge adjacent text segments with the same styles.
282	        if let Some(Segment::Text(last_len, last_styles)) = self.segments.last_mut()
283	            && *last_styles == styles
284	        {
285	            *last_len += segment_len;
286	            return;
287	        }
288	
289	        self.segments.push(Segment::Text(segment_len, styles));
290	    }
291	
292	    fn push_item(&mut self, item: Item<'a>) {
293	        match (self.segments.last_mut(), &item) {
294	            // Merge adjacent weak spacing by taking the maximum.
295	            (
296	                Some(Segment::Item(Item::Absolute(prev_amount, true))),
297	                Item::Absolute(amount, true),
298	            ) => {
299	                *prev_amount = (*prev_amount).max(*amount);
300	            }
301	
302	            _ => {
303	                self.full.push_str(item.textual());
304	                self.segments.push(Segment::Item(item));
305	            }
306	        }
307	    }
308	}
309	
310	/// Maps byte offsets back to spans.
311	#[derive(Default)]
312	pub struct SpanMapper(Vec<(usize, Span)>);
313	
314	impl SpanMapper {
315	    /// Create a new span mapper.
316	    pub fn new() -> Self {
317	        Self::default()
318	    }
319	
320	    /// Push a span for a segment with the given length.
321	    pub fn push(&mut self, len: usize, span: Span) {
322	        self.0.push((len, span));
323	    }
324	
325	    /// Determine the span at the given byte offset.
326	    ///
327	    /// May return a detached span.
328	    pub fn span_at(&self, offset: usize) -> (Span, u16) {
329	        let mut cursor = 0;
330	        for &(len, span) in &self.0 {
331	            if (cursor..cursor + len).contains(&offset) {
332	                return (span, u16::try_from(offset - cursor).unwrap_or(0));
333	            }
334	            cursor += len;
335	        }
336	        (Span::detached(), 0)
337	    }
338	}
