use std::ops::{Add, Sub};
use std::sync::LazyLock;

use az::SaturatingAs;
use icu_properties::CodePointMapDataBorrowed;
use icu_properties::props::LineBreak;
use icu_provider_blob::BlobDataProvider;
use icu_segmenter::options::LineBreakOptions;
